    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, node])
    node.ir_type == "Hash"
    entry := node.value[_]

    key_name := entry.key.value
    is_key_field_only(key_name)

    val := entry.value
    is_suspicious_key_value(val)

    result := {
        "type": "sec_hard_pass",
        "element": {
            "ir_type": "Attribute",
            "name": key_name,
            "value": val,
            "line": val.line,
            "column": val.column,
            "end_line": val.end_line,
            "end_column": val.end_column,
            "code": val.code
        },
        "path": parent.path,
        "description": "Use of Hard-coded Key - Keys should not be hard-coded in configuration files. Use secure external secret management instead. (CWE-259)"
    }
}

# Environment variable style credentials in Arrays
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, node])
    node.ir_type == "Array"
    elem := node.value[_]

    elem.ir_type == "String"
    contains_env_credential(elem.value)
    not glitch_lib.has_variable_reference(elem)

    parts := split(elem.value, "=")
    key_part := parts[0]
    is_password_field(lower(key_part))

    value_part := parts[1]
    value_part != ""
    value_part != "null"
    value_part != "nil"
    value_part != "undefined"

    result := {
        "type": "sec_hard_pass",
        "element": elem,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Password found in environment variable format. Use secure external secret management instead. (CWE-259)"
    }
}

# Check for any Variable names that contain password keywords (dotted notation like Chef)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check names like "default.sensu.rabbitmq.password" by checking if variable name contains password pattern
    contains_password_keyword(var.name)
    is_hardcoded_string(var.value)
    not looks_like_password_hash(var.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Passwords should not be hard-coded in variable definitions with dotted notation. Use secure external secret management instead. (CWE-259)"
    }
}

